      ".tutorial-panel[data-v-945af354]{position:fixed;z-index:75;top:50%;width:min(360px,calc(100vw - 48px));padding:22px 24px 20px;border:1px solid rgba(215,179,109,0.62);background:rgba(13,11,9,0.96);box-shadow:0 22px 70px rgba(0,0,0,0.54);color:#f7ecdc;transform:translateY(-50%);pointer-events:none}.tutorial-panel[data-placement='left'][data-v-945af354]{left:clamp(24px,5vw,72px)}.tutorial-panel[data-placement='right'][data-v-945af354]{right:clamp(24px,5vw,72px)}.tutorial-panel[data-placement='center'][data-v-945af354]{left:50%;transform:translate(-50%,-50%)}header[data-v-945af354],footer[data-v-945af354]{display:flex;align-items:center;justify-content:space-between;gap:18px}header small[data-v-945af354],footer span[data-v-945af354]{color:rgba(247,236,220,0.56);font-size:11px}button[data-v-945af354]{padding:7px 12px;border:1px solid rgba(247,236,220,0.24);background:transparent;color:#f7ecdc;cursor:pointer;font:inherit;pointer-events:auto}.tutorial-progress[data-v-945af354]{height:2px;margin:15px 0 20px;background:rgba(247,236,220,0.12)}.tutorial-progress i[data-v-945af354]{display:block;height:100%;background:#d7b36d;transition:width 180ms ease}h2[data-v-945af354]{margin:0;font-family:serif;font-size:24px;font-weight:500;letter-spacing:0}p[data-v-945af354]{margin:14px 0 22px;color:rgba(247,236,220,0.78);font-size:13px;line-height:1.75}footer[data-v-945af354]{justify-content:flex-end}footer button[data-v-945af354]{min-width:112px;border-color:rgba(215,179,109,0.7)}\n",
